/** @param {NS} ns */
export async function main(ns) {
  // Safely enumerate top-level ns properties
  const skip = ['buy','sell','install','attack','hack','start','stop','purchase','upgrade','donate','crime','join','quit','destroy','nuke','bribe','kickFromFaction','murder','assassin'];

  function isSafe(name) {
    const low = name.toLowerCase();
    return !skip.some(s => low.includes(s));
  }

  const results = {};

  // Get all property names from ns
  let props = [];
  try {
    props = Object.getOwnPropertyNames(ns);
  } catch(e) {
    props = Object.keys(ns);
  }

  // Also try common names
  const extras = ['help','docs','tutorial','print','tprint','scan','ls','ps','getHostname',
    'getServerMaxMoney','getServerMoneyAvailable','getPlayerInfo','getPlayer','getCharacterInfo',
    'getHackingLevel','getStats','getMoney','getBalance','getLevel','getUpgrades','getShop',
    'getAugmentations','getPurchasableAugs','getTasks','getCrimes','getGang','sleeve',
    'bladeburner','corporation','hacknet','stock','singularity','formulas','ui','args'];

  const allNames = [...new Set([...props, ...extras])];

  for (const key of allNames) {
    try {
      const val = ns[key];
      if (val === undefined) continue;
      const t = typeof val;
      if (t === 'object' && val !== null) {
        // Enumerate nested
        const nested = {};
        let subkeys = [];
        try { subkeys = Object.getOwnPropertyNames(val); } catch(e) { subkeys = Object.keys(val); }
        for (const sk of subkeys) {
          try {
            const sv = val[sk];
            nested[sk] = typeof sv;
          } catch(e) {
            nested[sk] = 'error:' + e.message;
          }
        }
        results[key] = { type: 'object', children: nested };
      } else if (t === 'function') {
        results[key] = { type: 'function' };
      } else {
        results[key] = { type: t, value: String(val).slice(0,100) };
      }
    } catch(e) {
      results[key] = { error: e.message };
    }
  }

  // Print in chunks
  const lines = JSON.stringify(results, null, 1).split('\n');
  for (let i = 0; i < lines.length; i += 20) {
    ns.tprint(lines.slice(i, i+20).join('\n'));
  }
}
